// Radio / podcast capsules: one episode per framework, a host talking with a veterinarian.
// tools/capsules.py turns this into MP3 (podcast) and WAV (broadcast) files per language; the
// kit page shows the transcript and cue sheet from the same data. Claims match the videos.
window.SPS_CAPSULES = {
  show: { fr: 'Santé animale, marchés ouverts', en: 'Healthy Animals, Open Markets', pt: 'Animais saudáveis, mercados abertos' },
  roles: {
    host: { fr: 'Animatrice', en: 'Host', pt: 'Apresentador' },
    vet: { fr: 'Vétérinaire', en: 'Veterinarian', pt: 'Veterinário' },
  },
  episodes: [
    {
      id: 'international', n: 1, video: 'international',
      title: { fr: 'Les normes internationales', en: 'International standards', pt: 'As normas internacionais' },
      lines: [
        { who: 'host', fr: 'Bienvenue dans « Santé animale, marchés ouverts », l’émission qui explique les règles sanitaires du commerce du bétail en Afrique de l’Ouest.', en: 'Welcome to Healthy Animals, Open Markets, the programme that explains the health rules of the livestock trade in West Africa.', pt: 'Bem-vindos a «Animais saudáveis, mercados abertos», o programa que explica as regras sanitárias do comércio de gado na África Ocidental.' },
        { who: 'host', fr: 'Aujourd’hui, un épisode complet sur les normes internationales. Pourquoi un acheteur à l’étranger peut-il faire confiance à votre viande ? Et quelles règles protègent à la fois la santé et le commerce ? Nous en parlons avec un vétérinaire.', en: 'Today, a full episode on international standards. Why can a buyer abroad trust your meat? And which rules protect both health and trade? We talk it through with a veterinarian.', pt: 'Hoje, um episódio completo sobre as normas internacionais. Porque é que um comprador no estrangeiro pode confiar na sua carne? E que regras protegem ao mesmo tempo a saúde e o comércio? Falamos disso com um veterinário.' },
        { who: 'vet', fr: 'Bonjour, et merci de m’accueillir.', en: 'Good morning, and thank you for having me.', pt: 'Bom dia, e obrigado pelo convite.' },
        { who: 'host', sting: true, fr: 'Commençons par une histoire. Aïcha dirige un petit abattoir. Des acheteurs d’une grande ville côtière, dans un pays voisin, veulent sa viande. Mais ils demandent une garantie : cette viande est-elle saine ?', en: 'Let’s start with a story. Aïcha runs a small abattoir. Buyers from a big coastal city, in a neighbouring country, want her meat. But they ask for a guarantee: is this meat safe?', pt: 'Comecemos por uma história. Aïcha dirige um pequeno matadouro. Compradores de uma grande cidade costeira, num país vizinho, querem a sua carne. Mas pedem uma garantia: esta carne é segura?' },
        { who: 'vet', fr: 'C’est la bonne question. Chaque pays fixe des règles sanitaires pour la viande qui entre. Si chacun inventait les siennes, chaque frontière exigerait autre chose, et des commerçantes comme Aïcha s’y perdraient.', en: 'That is the right question. Every country sets health rules for the meat it lets in. If each one invented its own, every border would ask for something different, and traders like Aïcha would be lost.', pt: 'É a pergunta certa. Cada país fixa regras sanitárias para a carne que entra. Se cada um inventasse as suas, cada fronteira exigiria outra coisa, e comerciantes como Aïcha ficariam perdidas.' },
        { who: 'host', fr: 'Alors, qui fixe les règles communes ?', en: 'So who sets the common rules?', pt: 'Então, quem fixa as regras comuns?' },
        { who: 'vet', fr: 'L’Organisation mondiale du commerce a un accord pour cela : l’Accord sur l’application des mesures sanitaires et phytosanitaires, l’Accord SPS.', en: 'The World Trade Organization has an agreement for this: the Agreement on the Application of Sanitary and Phytosanitary Measures, the SPS Agreement for short.', pt: 'A Organização Mundial do Comércio tem um acordo para isso: o Acordo sobre a Aplicação de Medidas Sanitárias e Fitossanitárias, o Acordo SPS.' },
        { who: 'host', sting: true, fr: 'Docteur, que dit d’abord l’Accord SPS ?', en: 'Doctor, what does the SPS Agreement say first?', pt: 'Doutor, o que diz primeiro o Acordo SPS?' },
        { who: 'vet', fr: 'Il commence par un droit. Chaque pays peut prendre les mesures nécessaires pour protéger la vie et la santé des personnes, des animaux et des végétaux.', en: 'It starts with a right. Every country may take the measures it needs to protect the life and health of people, animals and plants.', pt: 'Começa por um direito. Cada país pode tomar as medidas necessárias para proteger a vida e a saúde das pessoas, dos animais e das plantas.' },
        { who: 'host', fr: 'Un pays peut donc refuser une viande qu’il juge dangereuse ?', en: 'So a country can refuse meat it considers unsafe?', pt: 'Então um país pode recusar carne que considere perigosa?' },
        { who: 'vet', fr: 'Oui, mais dans certaines limites. Une mesure doit reposer sur des principes et des preuves scientifiques. Elle ne s’applique que dans la mesure nécessaire pour protéger la santé.', en: 'Yes, but within limits. A measure must rest on scientific principles and evidence. It applies only as far as needed to protect health.', pt: 'Sim, mas dentro de certos limites. Uma medida deve assentar em princípios e provas científicas. Só se aplica na medida necessária para proteger a saúde.' },
        { who: 'vet', fr: 'Elle ne doit pas faire de discrimination entre des pays où les mêmes conditions existent. Et elle ne doit jamais servir de barrière déguisée au commerce.', en: 'It must not discriminate between countries where the same conditions prevail. And it must never be used as a hidden barrier to trade.', pt: 'Não deve discriminar entre países onde existam as mesmas condições. E nunca deve servir de barreira disfarçada ao comércio.' },
        { who: 'host', fr: 'Comment un pays décide-t-il de ce qui est nécessaire ?', en: 'How does a country decide what is needed?', pt: 'Como decide um país o que é necessário?' },
        { who: 'vet', fr: 'En évaluant le risque, avec les méthodes des organisations internationales. Il tient compte des preuves scientifiques, des méthodes d’élevage et de transformation, et des maladies présentes.', en: 'By assessing the risk, using methods developed by the international organisations. It looks at the scientific evidence, at how animals are raised and processed, and at which diseases are present.', pt: 'Avaliando o risco, com os métodos das organizações internacionais. Tem em conta as provas científicas, os métodos de criação e de transformação, e as doenças presentes.' },
        { who: 'vet', fr: 'Puis il choisit une mesure qui protège assez, sans restreindre le commerce plus que nécessaire.', en: 'Then it chooses a measure that protects enough, without restricting trade more than required.', pt: 'Depois escolhe uma medida que protege o suficiente, sem restringir o comércio mais do que o necessário.' },
        { who: 'host', sting: true, fr: 'Vous parlez d’organisations internationales. Qui écrit les normes ?', en: 'You mentioned international organisations. Who writes the standards?', pt: 'Falou de organizações internacionais. Quem escreve as normas?' },
        { who: 'vet', fr: 'Trois organisations de référence : le Codex Alimentarius pour la sécurité des aliments, l’OMSA, l’Organisation mondiale de la santé animale, pour la santé animale, et la CIPV pour la santé des végétaux.', en: 'Three reference bodies: the Codex Alimentarius for food safety, WOAH, the World Organisation for Animal Health, for animal health, and the IPPC for plant health.', pt: 'Três organizações de referência: o Codex Alimentarius para a segurança dos alimentos, a OMSA, a Organização Mundial da Saúde Animal, para a saúde animal, e a CIPV para a sanidade vegetal.' },
        { who: 'host', fr: 'Chaque pays doit-il les suivre ?', en: 'Must every country follow them?', pt: 'Cada país tem de as seguir?' },
        { who: 'vet', fr: 'L’Accord demande de fonder les mesures sur ces normes. Une mesure qui leur est conforme est présumée nécessaire et conforme à l’Accord.', en: 'The Agreement asks countries to base their measures on these standards. A measure that follows them is presumed necessary and consistent with the Agreement.', pt: 'O Acordo pede que as medidas se baseiem nestas normas. Uma medida conforme a elas presume-se necessária e conforme ao Acordo.' },
        { who: 'vet', fr: 'Un pays peut protéger plus strictement que la norme, mais il lui faut alors une justification scientifique.', en: 'A country may protect more strictly than the standard, but then it needs a scientific justification.', pt: 'Um país pode proteger de forma mais estrita do que a norma, mas então precisa de uma justificação científica.' },
        { who: 'host', fr: 'Concrètement, pour un abattoir comme celui d’Aïcha ?', en: 'In practice, for an abattoir like Aïcha’s?', pt: 'Na prática, para um matadouro como o de Aïcha?' },
        { who: 'vet', fr: 'Prenons les médicaments. Si une vache a reçu un antibiotique, on respecte le délai d’attente avant l’abattage. Sinon, des résidus restent dans la viande, le contrôle les détecte, le lot est refusé et l’acheteur annule sa commande.', en: 'Take medicines. If a cow was given an antibiotic, you respect the withdrawal period before slaughter. Otherwise residues stay in the meat, the check detects them, the batch is refused and the buyer cancels the order.', pt: 'Pensemos nos medicamentos. Se uma vaca recebeu um antibiótico, respeita-se o intervalo de segurança antes do abate. Senão, ficam resíduos na carne, o controlo deteta-os, o lote é recusado e o comprador cancela a encomenda.' },
        { who: 'vet', fr: 'À l’abattoir, le vétérinaire inspecte les animaux vivants, puis chaque carcasse, et appose le cachet d’inspection. Locaux propres, eau potable et tenues de travail protègent le consommateur.', en: 'At the abattoir, the veterinarian inspects the live animals, then each carcass, and applies the inspection stamp. Clean premises, clean water and work clothes protect the consumer.', pt: 'No matadouro, o veterinário inspeciona os animais vivos, depois cada carcaça, e aplica o carimbo de inspeção. Instalações limpas, água potável e roupa de trabalho protegem o consumidor.' },
        { who: 'host', fr: 'Une question d’un boucher qui nous écoute : qui décide de la quantité de résidus de trop ?', en: 'A question from a butcher who listens to us: who decides how much residue is too much?', pt: 'Uma pergunta de um talhante que nos ouve: quem decide quantos resíduos são demais?' },
        { who: 'vet', fr: 'Pour les aliments, le Codex Alimentarius fixe des limites maximales de résidus pour les médicaments vétérinaires. Respecter le délai d’attente indiqué permet de rester sous ces limites.', en: 'For food, the Codex Alimentarius sets maximum residue limits for veterinary medicines. Respecting the withdrawal period on the label keeps meat below those limits.', pt: 'Para os alimentos, o Codex Alimentarius fixa limites máximos de resíduos para os medicamentos veterinários. Respeitar o intervalo de segurança indicado permite ficar abaixo desses limites.' },
        { who: 'host', sting: true, fr: 'Le pays des acheteurs ne contrôle pas la viande comme celui d’Aïcha. Son pays doit-il copier chaque méthode ?', en: 'The buyers’ country does not check meat the way Aïcha’s country does. Does her country have to copy every method?', pt: 'O país dos compradores não controla a carne como o de Aïcha. O país dela tem de copiar cada método?' },
        { who: 'vet', fr: 'Non. C’est l’équivalence, à l’article 4 de l’Accord. L’importateur doit accepter des mesures différentes comme équivalentes, si le pays exportateur démontre objectivement qu’elles atteignent son niveau de protection.', en: 'No. That is equivalence, in Article 4 of the Agreement. The importer must accept different measures as equivalent, if the exporting country objectively shows that they reach the importer’s level of protection.', pt: 'Não. É a equivalência, no artigo 4.º do Acordo. O importador deve aceitar medidas diferentes como equivalentes, se o país exportador demonstrar objetivamente que atingem o seu nível de proteção.' },
        { who: 'host', fr: 'Comment le démontrer ?', en: 'How does it show that?', pt: 'Como se demonstra isso?' },
        { who: 'vet', fr: 'Il fournit les données scientifiques et techniques, et donne à l’importateur un accès raisonnable pour les inspections et les tests.', en: 'It supplies the scientific and technical data, and gives the importer reasonable access for inspections and tests.', pt: 'Fornece os dados científicos e técnicos, e dá ao importador um acesso razoável para inspeções e testes.' },
        { who: 'vet', fr: 'De son côté, sur demande, l’importateur explique le risque visé par sa mesure. Le Comité SPS de l’OMC lui demande de répondre normalement dans les six mois, et une demande n’est pas, à elle seule, une raison d’arrêter le commerce en cours.', en: 'For its part, on request, the importer explains the risk its measure targets. The WTO’s SPS Committee asks it to reply normally within six months, and a request alone is no reason to stop trade already under way.', pt: 'Por seu lado, a pedido, o importador explica o risco visado pela sua medida. O Comité SPS da OMC pede-lhe que responda normalmente no prazo de seis meses, e um pedido, por si só, não é razão para interromper o comércio em curso.' },
        { who: 'host', sting: true, fr: 'Imaginons le pire. La fièvre aphteuse est signalée dans une région éloignée de celle d’Aïcha. Tout le pays doit-il arrêter de vendre ?', en: 'Let’s imagine the worst. Foot-and-mouth disease is reported in a region far from Aïcha’s. Does the whole country have to stop selling?', pt: 'Imaginemos o pior. É detetada febre aftosa numa região longe da de Aïcha. Todo o país tem de parar de vender?' },
        { who: 'vet', fr: 'Pas forcément. L’article 6 demande d’adapter les mesures à la situation sanitaire de chaque zone : tout un pays, une partie d’un pays, ou des parties de plusieurs pays.', en: 'Not necessarily. Article 6 says measures must fit the health situation of each area: a whole country, part of a country, or parts of several countries.', pt: 'Não necessariamente. O artigo 6.º pede que as medidas se adaptem à situação sanitária de cada zona: um país inteiro, parte de um país, ou partes de vários países.' },
        { who: 'vet', fr: 'Les pays reconnaissent les zones indemnes de maladie, et les zones à faible prévalence.', en: 'Countries must recognise disease-free areas, and areas of low disease prevalence.', pt: 'Os países devem reconhecer as zonas indemnes de doença, e as zonas de baixa prevalência.' },
        { who: 'host', fr: 'Que doit faire le pays d’Aïcha ?', en: 'What must Aïcha’s country do?', pt: 'O que deve fazer o país de Aïcha?' },
        { who: 'vet', fr: 'Déclarer le foyer à l’OMSA, placer la zone sous contrôle, et prouver, par la surveillance et les contrôles, que les autres zones sont indemnes. L’importateur peut obtenir un accès pour vérifier.', en: 'Report the outbreak to WOAH, put the zone under control, and prove, with surveillance and checks, that the other areas are free. The importer can be given access to check.', pt: 'Declarar o foco à OMSA, colocar a zona sob controlo, e provar, com vigilância e controlos, que as outras zonas estão indemnes. O importador pode ter acesso para verificar.' },
        { who: 'host', fr: 'Et si le pays ne dit rien, pour continuer à vendre ?', en: 'And if the country says nothing, to keep selling?', pt: 'E se o país não disser nada, para continuar a vender?' },
        { who: 'vet', fr: 'Alors la maladie gagne d’autres régions, la confiance est perdue, et les acheteurs ferment leurs portes à tout le pays. La transparence protège le commerce.', en: 'Then the disease spreads to other regions, trust is lost, and buyers close their doors to the whole country. Openness protects trade.', pt: 'Então a doença chega a outras regiões, a confiança perde-se, e os compradores fecham as portas a todo o país. A transparência protege o comércio.' },
        { who: 'host', fr: 'Est-ce que cela ne concerne que les animaux ?', en: 'Does this only concern animals?', pt: 'Isto só diz respeito aos animais?' },
        { who: 'vet', fr: 'Non. Le même principe vaut pour les organismes nuisibles aux végétaux : les zones qui en sont exemptes sont reconnues elles aussi.', en: 'No. The same principle applies to plant pests: pest-free areas are recognised too.', pt: 'Não. O mesmo princípio vale para as pragas das plantas: as zonas livres de pragas também são reconhecidas.' },
        { who: 'host', sting: true, fr: 'À la frontière, comment les contrôles doivent-ils se passer ?', en: 'At the border, how should the checks go?', pt: 'Na fronteira, como devem decorrer os controlos?' },
        { who: 'vet', fr: 'Les contrôles aussi ont des règles. Les inspections se font sans retard injustifié, et les produits importés ne sont pas traités moins bien que les produits locaux.', en: 'Checks have rules too. Inspections must be carried out without undue delay, and imported products are treated no less favourably than local ones.', pt: 'Os controlos também têm regras. As inspeções fazem-se sem atrasos injustificados, e os produtos importados não são tratados pior do que os produtos locais.' },
        { who: 'host', fr: 'Et comment un commerçant connaît-il les règles ?', en: 'And how does a trader find out the rules?', pt: 'E como fica um comerciante a conhecer as regras?' },
        { who: 'vet', fr: 'Chaque pays publie ses mesures SPS et notifie leurs changements à l’OMC. Chacun tient aussi un point d’information qui répond aux questions sur ces mesures.', en: 'Each country publishes its SPS measures and notifies changes to the WTO. Each one also runs an enquiry point that answers questions about its measures.', pt: 'Cada país publica as suas medidas SPS e notifica as alterações à OMC. Cada um mantém também um ponto de informação que responde a perguntas sobre essas medidas.' },
        { who: 'host', fr: 'Et pour les pays qui ont du mal à respecter toutes ces règles ?', en: 'And for countries that find all these rules hard to meet?', pt: 'E para os países que têm dificuldade em cumprir todas estas regras?' },
        { who: 'vet', fr: 'L’Accord reconnaît leurs difficultés. Il prévoit une assistance technique, par exemple pour renforcer les services vétérinaires, les laboratoires et les autorités de contrôle.', en: 'The Agreement recognises their difficulties. It provides for technical assistance, for example to strengthen veterinary services, laboratories and regulatory bodies.', pt: 'O Acordo reconhece as suas dificuldades. Prevê assistência técnica, por exemplo para reforçar os serviços veterinários, os laboratórios e as autoridades de controlo.' },
        { who: 'vet', fr: 'Et pour le voyage : la viande part en camion réfrigéré, et la chaîne du froid n’est jamais rompue. Sans froid, les microbes se multiplient et la viande est refusée à l’arrivée.', en: 'And for the journey: meat travels in a refrigerated truck, and the cold chain is never broken. Without cold, microbes multiply and the meat is refused on arrival.', pt: 'E para a viagem: a carne segue num camião frigorífico, e a cadeia de frio nunca é interrompida. Sem frio, os micróbios multiplicam-se e a carne é recusada à chegada.' },
        { who: 'host', sting: true, fr: 'Un dernier texte international concerne les tout-petits.', en: 'One last international text concerns the youngest.', pt: 'Um último texto internacional diz respeito aos mais pequenos.' },
        { who: 'vet', fr: 'Oui : le Code international de commercialisation des substituts du lait maternel, de l’OMS. Il protège l’allaitement. Ces produits ne doivent pas faire l’objet de publicité auprès du public, et les mères ne doivent pas recevoir d’échantillons gratuits.', en: 'Yes: the WHO International Code of Marketing of Breast-milk Substitutes. It protects breastfeeding. These products should not be advertised to the general public, and mothers should not be given free samples.', pt: 'Sim: o Código Internacional de Comercialização de Substitutos do Leite Materno, da OMS. Protege o aleitamento. Estes produtos não devem ser publicitados ao público, e as mães não devem receber amostras grátis.' },
        { who: 'vet', fr: 'Et leurs étiquettes doivent rappeler la supériorité de l’allaitement maternel.', en: 'And their labels should state that breastfeeding is best for babies.', pt: 'E os rótulos devem lembrar a superioridade do aleitamento materno.' },
        { who: 'host', sting: true, fr: 'Docteur, que doivent retenir nos auditeurs ?', en: 'Doctor, what should our listeners remember?', pt: 'Doutor, o que devem reter os nossos ouvintes?' },
        { who: 'vet', fr: 'Quatre principes. Les mesures reposent sur la science. Les pays partagent des normes internationales communes. Des méthodes différentes peuvent être équivalentes si elles protègent autant. Et les zones indemnes peuvent continuer à commercer.', en: 'Four principles. Measures rest on science. Countries share common international standards. Different methods can be equivalent if they protect as well. And disease-free zones can keep trading.', pt: 'Quatro princípios. As medidas assentam na ciência. Os países partilham normas internacionais comuns. Métodos diferentes podem ser equivalentes se protegerem tanto quanto. E as zonas indemnes podem continuar a comerciar.' },
        { who: 'host', fr: 'Et pour un éleveur, un commerçant ou un abattoir ?', en: 'And for a farmer, a trader or an abattoir?', pt: 'E para um criador, um comerciante ou um matadouro?' },
        { who: 'vet', fr: 'Trois réflexes : respecter le délai d’attente des médicaments, faire inspecter les animaux et les carcasses, et garder la viande au froid jusqu’au client.', en: 'Three habits: respect medicine withdrawal periods, have animals and carcasses inspected, and keep meat cold all the way to the customer.', pt: 'Três reflexos: respeitar o intervalo de segurança dos medicamentos, mandar inspecionar os animais e as carcaças, e manter a carne no frio até ao cliente.' },
        { who: 'host', fr: 'Merci, docteur.', en: 'Thank you, Doctor.', pt: 'Obrigado, doutor.' },
        { who: 'host', sting: true, fr: 'À retenir : des normes communes, une viande saine, des marchés ouverts. À bientôt sur « Santé animale, marchés ouverts ».', en: 'Remember: common standards, safe meat, open markets. See you next time on Healthy Animals, Open Markets.', pt: 'A reter: normas comuns, carne saudável, mercados abertos. Até breve em «Animais saudáveis, mercados abertos».' },
      ],
    },
    {
      id: 'ecowas', n: 2, video: 'ecowas',
      title: { fr: 'Passer la frontière avec son troupeau (CEDEAO)', en: 'Crossing the border with a herd (ECOWAS)', pt: 'Atravessar a fronteira com o rebanho (CEDEAO)' },
      lines: [
        { who: 'host', fr: 'Bienvenue dans « Santé animale, marchés ouverts ». Aujourd’hui, un épisode complet sur les règles de la CEDEAO pour faire passer les frontières aux animaux, et sur le règlement qui les fixe.', en: 'Welcome to Healthy Animals, Open Markets. Today, a full episode on the ECOWAS rules for moving animals across borders, and the regulation behind them.', pt: 'Bem-vindos a «Animais saudáveis, mercados abertos». Hoje, um episódio completo sobre as regras da CEDEAO para fazer atravessar fronteiras aos animais, e sobre o regulamento que as fixa.' },
        { who: 'host', fr: 'Avec nous, un vétérinaire. Docteur, bienvenue.', en: 'With us, a veterinarian. Doctor, welcome.', pt: 'Connosco, um veterinário. Doutor, bem-vindo.' },
        { who: 'vet', fr: 'Merci, c’est un plaisir.', en: 'Thank you, it’s a pleasure.', pt: 'Obrigado, é um prazer.' },
        { who: 'host', sting: true, fr: 'Commençons par une histoire. Moussa est commerçant de bétail au Sahel. Il veut vendre quarante bœufs sur un grand marché, de l’autre côté de la frontière. À quoi doit-il penser d’abord ?', en: 'Let’s start with a story. Moussa is a livestock trader in the Sahel. He wants to sell forty cattle at a big market across the border. What should he think about first?', pt: 'Comecemos por uma história. Moussa é comerciante de gado no Sahel. Quer vender quarenta bois num grande mercado do outro lado da fronteira. Em que deve pensar primeiro?' },
        { who: 'vet', fr: 'Que les animaux voyagent, et les maladies avec eux. Une seule bête malade peut contaminer d’autres troupeaux tout au long de la route.', en: 'That animals travel, and diseases travel with them. One sick animal can infect other herds all along the route.', pt: 'Que os animais viajam, e as doenças com eles. Um só animal doente pode contaminar outros rebanhos ao longo do caminho.' },
        { who: 'host', fr: 'Alors, qui fixe les règles de ces voyages ?', en: 'So who sets the rules for these journeys?', pt: 'Então, quem fixa as regras destas viagens?' },
        { who: 'vet', fr: 'La CEDEAO. En 2010, elle a adopté un règlement qui harmonise les règles sanitaires des végétaux, des animaux et des aliments dans toute la région. Il s’applique à toutes les étapes, de la production à la distribution.', en: 'ECOWAS. In 2010 it adopted a regulation that harmonises the health rules for plants, animals and food across the region. It applies at every stage, from production to distribution.', pt: 'A CEDEAO. Em 2010, adotou um regulamento que harmoniza as regras sanitárias dos vegetais, dos animais e dos alimentos em toda a região. Aplica-se a todas as etapas, da produção à distribuição.' },
        { who: 'host', fr: 'Pourquoi est-ce si important ?', en: 'Why does it matter so much?', pt: 'Porque é tão importante?' },
        { who: 'vet', fr: 'Parce que, comme le dit le règlement lui-même, la bonne santé humaine dépend à bien des égards de la bonne santé animale.', en: 'Because, as the regulation itself says, good human health depends in many ways on good animal health.', pt: 'Porque, como diz o próprio regulamento, a boa saúde humana depende em muitos aspetos da boa saúde animal.' },
        { who: 'host', fr: 'Et qui est concerné ?', en: 'And who does it cover?', pt: 'E quem abrange?' },
        { who: 'vet', fr: 'Tous les animaux, domestiques et sauvages, terrestres et aquatiques, et les produits qui en viennent. Et tous ceux qui les produisent, les transforment, les emballent, les transportent, les stockent ou les vendent : le règlement les appelle des opérateurs économiques.', en: 'All animals, domestic and wild, on land and in water, and the products that come from them. And everyone who produces, processes, packs, transports, stores or sells them: the regulation calls them economic operators.', pt: 'Todos os animais, domésticos e selvagens, terrestres e aquáticos, e os produtos que deles vêm. E todos os que os produzem, transformam, embalam, transportam, armazenam ou vendem: o regulamento chama-lhes operadores económicos.' },
        { who: 'host', sting: true, fr: 'Quels principes fixe-t-il ?', en: 'What principles does it set?', pt: 'Que princípios fixa?' },
        { who: 'vet', fr: 'D’abord, les pays fondent leurs mesures sur les normes internationales : le Codex Alimentarius, les accords de l’OMC, la CIPV et l’OMSA, l’Organisation mondiale de la santé animale.', en: 'First, countries base their measures on international standards: the Codex Alimentarius, the WTO agreements, the IPPC and WOAH, the World Organisation for Animal Health.', pt: 'Primeiro, os países baseiam as suas medidas nas normas internacionais: o Codex Alimentarius, os acordos da OMC, a CIPV e a OMSA, a Organização Mundial da Saúde Animal.' },
        { who: 'vet', fr: 'Ensuite, ils évaluent les risques sur des données scientifiques, et gardent des mesures proportionnées au risque.', en: 'Then they assess risks on scientific data, and keep measures in proportion to the risk.', pt: 'Depois, avaliam os riscos com base em dados científicos, e mantêm medidas proporcionais ao risco.' },
        { who: 'host', fr: 'Et si la science n’est pas encore sûre ?', en: 'And if the science isn’t settled yet?', pt: 'E se a ciência ainda não tiver certezas?' },
        { who: 'vet', fr: 'L’absence de certitude scientifique absolue n’est pas un prétexte pour retarder des mesures efficaces. Mais les mesures provisoires ne doivent pas restreindre le commerce plus que nécessaire.', en: 'A lack of full scientific certainty is no excuse to delay effective measures. But provisional measures must not restrict trade more than necessary.', pt: 'A falta de certeza científica absoluta não é pretexto para adiar medidas eficazes. Mas as medidas provisórias não devem restringir o comércio mais do que o necessário.' },
        { who: 'host', fr: 'Cela veut dire la libre circulation pour des commerçants comme Moussa ?', en: 'Does that mean free movement for traders like Moussa?', pt: 'Isso quer dizer livre circulação para comerciantes como Moussa?' },
        { who: 'vet', fr: 'Oui, pour les animaux et les produits conformes aux normes communautaires. Chaque pays accepte ce qui est conforme aux normes d’un autre État membre. Et toute personne contrôlée a droit à la transparence, à l’impartialité et à la proportionnalité.', en: 'Yes, for animals and products that meet community standards. Each country accepts what meets the standards of another member state. And anyone being inspected is entitled to transparency, impartiality and proportionality.', pt: 'Sim, para os animais e produtos conformes às normas comunitárias. Cada país aceita o que está conforme às normas de outro Estado-membro. E quem é controlado tem direito à transparência, à imparcialidade e à proporcionalidade.' },
        { who: 'host', fr: 'Et qui veille à ce que les règles soient les mêmes partout ?', en: 'And who makes sure the rules are the same everywhere?', pt: 'E quem garante que as regras são as mesmas em todo o lado?' },
        { who: 'vet', fr: 'Chaque année, les États passent en revue les règles sanitaires qui touchent le commerce régional, et la Commission travaille à les harmoniser. Les règles nationales doivent être cohérentes, simples et transparentes, sans entraves inutiles au commerce.', en: 'Each year, member states review the health rules that affect regional trade, and the Commission works on harmonising them. National rules must be coherent, simple and transparent, with no needless barriers to trade.', pt: 'Todos os anos, os Estados revêm as regras sanitárias que afetam o comércio regional, e a Comissão trabalha para as harmonizar. As regras nacionais devem ser coerentes, simples e transparentes, sem entraves inúteis ao comércio.' },
        { who: 'host', sting: true, fr: 'Qui fait quoi dans tout cela ?', en: 'Who does what in all this?', pt: 'Quem faz o quê em tudo isto?' },
        { who: 'vet', fr: 'Chaque pays a une administration vétérinaire. Elle désigne l’autorité responsable des mesures zoosanitaires et des certificats vétérinaires. Les vétérinaires officiels contrôlent et certifient les animaux.', en: 'Each country has a veterinary administration. It names the authority responsible for animal health measures and veterinary certificates. Official veterinarians check and certify the animals.', pt: 'Cada país tem uma administração veterinária. Designa a autoridade responsável pelas medidas zoossanitárias e pelos certificados veterinários. Os veterinários oficiais controlam e certificam os animais.' },
        { who: 'vet', fr: 'L’État peut aussi confier un mandat sanitaire à des vétérinaires privés : prophylaxie de masse, surveillance épidémiologique, inspection.', en: 'The State can also give private vets a sanitary mandate: mass disease prevention, epidemiological surveillance and inspection.', pt: 'O Estado também pode confiar um mandato sanitário a veterinários privados: profilaxia em massa, vigilância epidemiológica e inspeção.' },
        { who: 'host', fr: 'Et au niveau régional ?', en: 'And at the regional level?', pt: 'E a nível regional?' },
        { who: 'vet', fr: 'Un comité régional conseille la Commission de la CEDEAO, et des réseaux relient les pays : experts, laboratoires, alerte, organismes nationaux et institutions de formation.', en: 'A regional committee advises the ECOWAS Commission, and networks link the countries: experts, laboratories, alerts, national bodies and training institutions.', pt: 'Um comité regional aconselha a Comissão da CEDEAO, e redes ligam os países: peritos, laboratórios, alerta, organismos nacionais e instituições de formação.' },
        { who: 'host', sting: true, fr: 'Revenons à Moussa. Avant de partir, que doit-il faire ?', en: 'Back to Moussa. Before leaving, what should he do?', pt: 'Voltemos a Moussa. Antes de partir, o que deve fazer?' },
        { who: 'vet', fr: 'Faire examiner ses animaux par un vétérinaire officiel. S’ils sont sains, le vétérinaire délivre un certificat vétérinaire. Il accompagne le troupeau et se présente aux postes de contrôle sur la route.', en: 'Have an official veterinarian examine his animals. If they are healthy, the vet issues a veterinary certificate. It goes with the herd and is shown at the control posts on the route.', pt: 'Mandar examinar os animais por um veterinário oficial. Se estiverem saudáveis, o veterinário emite um certificado veterinário. Acompanha o rebanho e é apresentado nos postos de controlo do percurso.' },
        { who: 'host', fr: 'Et sans ce certificat ?', en: 'And without it?', pt: 'E sem esse certificado?' },
        { who: 'vet', fr: 'Le troupeau est arrêté à la frontière. Attente, contrôles, des jours et de l’argent perdus.', en: 'The herd is stopped at the border. Waiting, checks, lost days and lost money.', pt: 'O rebanho é parado na fronteira. Espera, controlos, dias e dinheiro perdidos.' },
        { who: 'host', fr: 'Et à la frontière, comment cela se passe-t-il ?', en: 'And what happens at the border itself?', pt: 'E na fronteira, como se passa?' },
        { who: 'vet', fr: 'Chaque pays fixe la liste des postes frontaliers par lesquels les animaux peuvent entrer. Si des animaux sont atteints d’une maladie à déclaration obligatoire, le pays peut refuser leur entrée ou les mettre en quarantaine, et il doit communiquer ces mesures immédiatement, avec leurs motifs.', en: 'Each country lists the border posts where animals may enter. If animals carry a notifiable disease, the country can refuse them or put them in quarantine, and it must report those measures straight away, with the reasons.', pt: 'Cada país fixa a lista dos postos fronteiriços por onde os animais podem entrar. Se os animais tiverem uma doença de declaração obrigatória, o país pode recusar a entrada ou pô-los em quarentena, e deve comunicar essas medidas de imediato, com os motivos.' },
        { who: 'host', fr: 'Et pour les animaux qui arrivent de l’extérieur de la région ?', en: 'And for animals arriving from outside the region?', pt: 'E para os animais que chegam de fora da região?' },
        { who: 'vet', fr: 'Ils passent une visite sanitaire au poste frontalier, aux frais de l’importateur. Seuls les animaux reconnus sains entrent, et ceux qui arrivent sans certificat sont refoulés ou mis en quarantaine aux frais de leurs propriétaires.', en: 'They get a health inspection at the border post, paid by the importer. Only animals found healthy come in, and those arriving without a certificate are turned back or quarantined at the owner’s expense.', pt: 'Passam uma inspeção sanitária no posto fronteiriço, paga pelo importador. Só entram os animais reconhecidos como saudáveis, e os que chegam sem certificado são recusados ou postos em quarentena à custa dos donos.' },
        { who: 'host', sting: true, fr: 'Beaucoup d’éleveurs se déplacent au fil des saisons. Et la transhumance ?', en: 'Many herders move with the seasons. What about transhumance?', pt: 'Muitos criadores deslocam-se ao ritmo das estações. E a transumância?' },
        { who: 'vet', fr: 'Le règlement la reconnaît comme un mode d’élevage utile, mais aussi comme une source de problèmes sanitaires et sociaux. Les États membres facilitent la circulation des troupeaux transhumants, avec le certificat international de transhumance de la CEDEAO.', en: 'The regulation calls it a useful way of raising livestock, but also a source of health and social problems. Member states make it easier for transhumant herds to cross borders, with the ECOWAS international transhumance certificate.', pt: 'O regulamento reconhece-a como um modo de criação útil, mas também como uma fonte de problemas sanitários e sociais. Os Estados-membros facilitam a circulação dos rebanhos transumantes, com o certificado internacional de transumância da CEDEAO.' },
        { who: 'host', sting: true, fr: 'Imaginons qu’au marché, Moussa voie des animaux qui toussent et respirent mal.', en: 'Now imagine that at the market, Moussa sees animals coughing and short of breath.', pt: 'Imaginemos que, no mercado, Moussa vê animais que tossem e respiram mal.' },
        { who: 'vet', fr: 'Ce pourrait être une maladie à déclaration obligatoire. Toute suspicion doit être portée immédiatement à la connaissance de l’autorité vétérinaire. Se taire, c’est laisser la maladie passer de troupeau en troupeau.', en: 'It could be a notifiable disease. Any suspicion must be brought to the veterinary authority at once. Keeping quiet lets the disease spread from herd to herd.', pt: 'Pode ser uma doença de declaração obrigatória. Qualquer suspeita deve ser levada de imediato ao conhecimento da autoridade veterinária. Calar-se é deixar a doença passar de rebanho em rebanho.' },
        { who: 'host', fr: 'Et une fois l’alerte donnée ?', en: 'And once the alert is given?', pt: 'E depois de dado o alerta?' },
        { who: 'vet', fr: 'Les autorités déclarent la maladie et appliquent des mesures dans un périmètre déterminé. Le pays prévient la Commission de la CEDEAO et les autres États par le réseau d’alerte, et informe l’OMSA.', en: 'The authorities declare the disease and apply measures within a defined area. The country warns the ECOWAS Commission and the other states through the alert network, and informs WOAH.', pt: 'As autoridades declaram a doença e aplicam medidas num perímetro determinado. O país avisa a Comissão da CEDEAO e os outros Estados através da rede de alerta, e informa a OMSA.' },
        { who: 'host', fr: 'Tout le pays arrête-t-il de commercer ?', en: 'Does the whole country stop trading?', pt: 'Todo o país deixa de comerciar?' },
        { who: 'vet', fr: 'Pas forcément. Les autres États peuvent ne restreindre que les animaux venant des parties du territoire où la maladie est apparue, et tout le pays seulement si elle s’étend largement. Les mesures prennent fin une fois la maladie éradiquée.', en: 'Not necessarily. Other states can restrict only the animals from the parts of the territory where the disease appeared, and the whole country only if it spreads widely. The measures end once the disease is eradicated.', pt: 'Não necessariamente. Os outros Estados podem restringir apenas os animais vindos das partes do território onde a doença apareceu, e todo o país só se ela se alastrar muito. As medidas terminam quando a doença é erradicada.' },
        { who: 'host', fr: 'Et si un pays n’arrive pas à faire face ?', en: 'And if a country can’t cope?', pt: 'E se um país não conseguir fazer face?' },
        { who: 'vet', fr: 'La Commission de la CEDEAO peut alors réunir d’urgence les organismes nationaux pour arrêter des mesures de substitution. Le règlement prévoit aussi un fonds d’urgence contre les maladies animales transfrontalières.', en: 'Then the ECOWAS Commission can urgently call the national bodies together to agree substitute measures. The regulation also plans an emergency fund against cross-border animal diseases.', pt: 'A Comissão da CEDEAO pode então reunir com urgência os organismos nacionais para decidir medidas de substituição. O regulamento prevê também um fundo de emergência contra as doenças animais transfronteiriças.' },
        { who: 'host', sting: true, fr: 'Et la viande, le lait, les cuirs ?', en: 'What about meat, milk or hides?', pt: 'E a carne, o leite, os couros?' },
        { who: 'vet', fr: 'Les produits animaux envoyés vers un autre État membre sont eux aussi accompagnés d’un certificat vétérinaire. Pour l’exportation hors de la région, cuirs, peaux et cornes demandent un certificat d’origine et un certificat de désinfection.', en: 'Animal products sent to another member state also travel with a veterinary certificate. For export outside the region, hides, skins and horns need a certificate of origin and a disinfection certificate.', pt: 'Os produtos animais enviados para outro Estado-membro também seguem com um certificado veterinário. Na exportação para fora da região, couros, peles e chifres exigem um certificado de origem e um certificado de desinfeção.' },
        { who: 'host', fr: 'Et qui répond de la sécurité des aliments ?', en: 'And who is responsible for food safety?', pt: 'E quem responde pela segurança dos alimentos?' },
        { who: 'vet', fr: 'Les opérateurs du secteur alimentaire répondent de ce qu’ils mettent sur le marché, et doivent vendre des produits sûrs. S’ils pensent qu’un produit peut nuire à la santé, ils informent les autorités et agissent pour protéger les consommateurs.', en: 'Food businesses answer for what they place on the market, and must sell safe products. If they think a product could harm health, they inform the authorities and act to protect consumers.', pt: 'Os operadores do setor alimentar respondem pelo que colocam no mercado, e devem vender produtos seguros. Se pensarem que um produto pode prejudicar a saúde, informam as autoridades e agem para proteger os consumidores.' },
        { who: 'host', fr: 'Et que peuvent faire les inspecteurs ?', en: 'And what can inspectors do?', pt: 'E o que podem fazer os inspetores?' },
        { who: 'vet', fr: 'Visiter les locaux, saisir des documents, prélever des échantillons et consigner des denrées. Ils peuvent demander qu’une denrée non conforme soit saisie, détruite ou réorientée. En cas de danger grave, l’organisme national peut suspendre la vente et retirer le produit.', en: 'Visit premises, take documents and samples, and hold foods. They can ask for non-compliant food to be seized, destroyed or redirected. In serious danger, the national body can suspend sales and withdraw the product.', pt: 'Visitar as instalações, apreender documentos, colher amostras e reter alimentos. Podem pedir que um alimento não conforme seja apreendido, destruído ou reencaminhado. Em caso de perigo grave, o organismo nacional pode suspender a venda e retirar o produto.' },
        { who: 'host', fr: 'Et que demande-t-on aux autorités ?', en: 'And what is asked of the authorities?', pt: 'E o que se pede às autoridades?' },
        { who: 'vet', fr: 'D’associer les acteurs concernés aux décisions, de les informer des risques, et de mener des campagnes de sensibilisation, comme cette émission.', en: 'To involve the people concerned in decisions, to keep them informed about risks, and to run awareness campaigns, like this programme.', pt: 'Associar os intervenientes às decisões, informá-los sobre os riscos, e fazer campanhas de sensibilização, como este programa.' },
        { who: 'host', sting: true, fr: 'Docteur, que doivent retenir nos auditeurs ?', en: 'Doctor, what should our listeners remember?', pt: 'Doutor, o que devem reter os nossos ouvintes?' },
        { who: 'vet', fr: 'Quatre règles. Les mesures reposent sur les normes internationales et la science. Les animaux et produits conformes circulent librement. Le certificat vétérinaire accompagne le troupeau et se présente aux postes. Et toute maladie suspecte se signale immédiatement.', en: 'Four rules. Measures rest on international standards and science. Compliant animals and products move freely. The veterinary certificate goes with the herd and is shown at the posts. And any suspected disease is reported at once.', pt: 'Quatro regras. As medidas assentam nas normas internacionais e na ciência. Os animais e produtos conformes circulam livremente. O certificado veterinário acompanha o rebanho e é apresentado nos postos. E qualquer doença suspeita é comunicada de imediato.' },
        { who: 'host', fr: 'Merci, docteur.', en: 'Thank you, Doctor.', pt: 'Obrigado, doutor.' },
        { who: 'host', sting: true, fr: 'Trois réflexes : le vétérinaire avant le départ, le certificat avec le troupeau, le contrôle à la frontière. À bientôt sur « Santé animale, marchés ouverts ».', en: 'Three habits: the veterinarian before you leave, the certificate with the herd, the check at the border. See you next time on Healthy Animals, Open Markets.', pt: 'Três reflexos: o veterinário antes da partida, o certificado com o rebanho, o controlo na fronteira. Até breve em «Animais saudáveis, mercados abertos».' },
      ],
    },
    {
      id: 'waemu', n: 3, video: 'waemu',
      title: { fr: 'Du troupeau à l’assiette (UEMOA)', en: 'From herd to plate (WAEMU)', pt: 'Do rebanho ao prato (UEMOA)' },
      lines: [
        { who: 'host', fr: 'Bienvenue dans « Santé animale, marchés ouverts ». Aujourd’hui, un épisode complet sur la sécurité sanitaire de la viande dans l’UEMOA, du troupeau à l’assiette.', en: 'Welcome to Healthy Animals, Open Markets. Today, a full episode on meat safety in the WAEMU area, from herd to plate.', pt: 'Bem-vindos a «Animais saudáveis, mercados abertos». Hoje, um episódio completo sobre a segurança sanitária da carne na UEMOA, do rebanho ao prato.' },
        { who: 'host', fr: 'Notre invité est vétérinaire. Docteur, bienvenue.', en: 'Our guest is a veterinarian. Doctor, welcome.', pt: 'O nosso convidado é veterinário. Doutor, bem-vindo.' },
        { who: 'vet', fr: 'Merci de m’accueillir.', en: 'Thank you for having me.', pt: 'Obrigado pelo convite.' },
        { who: 'host', sting: true, fr: 'Nous suivons Koffi, boucher au marché de la ville. Sa viande vient d’éleveurs, passe par le marché à bétail et l’abattoir, avant d’arriver chez ses clients. Docteur, quel texte fixe les règles ?', en: 'We follow Koffi, a butcher at the city market. His meat comes from herders, through the livestock market and the abattoir, to his customers. Doctor, which text sets the rules?', pt: 'Seguimos Koffi, talhante no mercado da cidade. A sua carne vem de criadores, passa pelo mercado de gado e pelo matadouro, antes de chegar aos clientes. Doutor, que texto fixa as regras?' },
        { who: 'vet', fr: 'Le Règlement numéro 007 de 2007 de l’UEMOA, sur la sécurité sanitaire des végétaux, des animaux et des aliments. Il s’applique à toutes les étapes de la production, de la transformation et de la distribution.', en: 'WAEMU Regulation number 007 of 2007, on the health safety of plants, animals and food. It applies at every stage of production, processing and distribution.', pt: 'O Regulamento número 007 de 2007 da UEMOA, sobre a segurança sanitária dos vegetais, dos animais e dos alimentos. Aplica-se a todas as etapas da produção, da transformação e da distribuição.' },
        { who: 'host', fr: 'Et qui est concerné ?', en: 'And who does it concern?', pt: 'E quem abrange?' },
        { who: 'vet', fr: 'Tous ceux qui produisent, transforment, emballent, transportent, stockent ou vendent des animaux, des produits animaux ou des aliments. Le règlement les appelle des opérateurs économiques, et Koffi en fait partie.', en: 'Everyone who produces, processes, packs, transports, stores or sells animals, animal products or food. The regulation calls them economic operators, and Koffi is one of them.', pt: 'Todos os que produzem, transformam, embalam, transportam, armazenam ou vendem animais, produtos animais ou alimentos. O regulamento chama-lhes operadores económicos, e Koffi é um deles.' },
        { who: 'host', fr: 'Sur quels principes ?', en: 'On what principles?', pt: 'Com que princípios?' },
        { who: 'vet', fr: 'Les mesures suivent les normes internationales : Codex Alimentarius, accords de l’OMC, CIPV et OMSA. Les risques sont évalués sur des données scientifiques, et les mesures restent proportionnées.', en: 'Measures follow international standards: the Codex Alimentarius, the WTO agreements, the IPPC and WOAH. Risks are assessed on scientific data, and measures stay proportionate.', pt: 'As medidas seguem as normas internacionais: Codex Alimentarius, acordos da OMC, CIPV e OMSA. Os riscos são avaliados com base em dados científicos, e as medidas mantêm-se proporcionais.' },
        { who: 'host', fr: 'Et quand la science hésite ?', en: 'And when the science is uncertain?', pt: 'E quando a ciência hesita?' },
        { who: 'vet', fr: 'Face à un risque de dommage grave ou irréversible, l’absence de certitude scientifique absolue n’est pas un prétexte pour remettre à plus tard des mesures efficaces. Et les risques s’expliquent ouvertement, avec les consommateurs et les professionnels.', en: 'Faced with a risk of serious or irreversible harm, a lack of full scientific certainty is no excuse to put off effective measures. And risks are discussed openly, with consumers and professionals.', pt: 'Perante um risco de dano grave ou irreversível, a falta de certeza científica absoluta não é pretexto para adiar medidas eficazes. E os riscos explicam-se abertamente, com os consumidores e os profissionais.' },
        { who: 'host', sting: true, fr: 'Qui fait quoi ?', en: 'Who does what?', pt: 'Quem faz o quê?' },
        { who: 'vet', fr: 'Auprès de la Commission de l’UEMOA, un comité régional de sécurité sanitaire donne des avis techniques. Pour les animaux, il s’appuie sur le Comité vétérinaire. Des réseaux d’experts, de laboratoires et d’alerte relient les États membres.', en: 'Under the WAEMU Commission, a regional health safety committee gives technical advice. For animals, it relies on the Veterinary Committee. Networks of experts, laboratories and alerts link the member states.', pt: 'Junto da Comissão da UEMOA, um comité regional de segurança sanitária dá pareceres técnicos. Para os animais, apoia-se no Comité veterinário. Redes de peritos, laboratórios e alerta ligam os Estados-membros.' },
        { who: 'vet', fr: 'Dans chaque État, une administration vétérinaire gère la santé animale et les certificats, et un organisme national gère les risques liés aux aliments.', en: 'In each state, a veterinary administration handles animal health and certificates, and a national body manages food risks.', pt: 'Em cada Estado, uma administração veterinária trata da saúde animal e dos certificados, e um organismo nacional gere os riscos dos alimentos.' },
        { who: 'host', fr: 'Et les consommateurs ?', en: 'And consumers?', pt: 'E os consumidores?' },
        { who: 'vet', fr: 'Chaque État a un conseil consultatif d’analyse des risques, où siègent les administrations, les organisations professionnelles et les consommateurs.', en: 'Each state has an advisory council on food risks, where officials, professional organisations and consumers are represented.', pt: 'Cada Estado tem um conselho consultivo de análise dos riscos, onde estão representadas as administrações, as organizações profissionais e os consumidores.' },
        { who: 'host', fr: 'Et comment les États travaillent-ils ensemble ?', en: 'And how do the states work together?', pt: 'E como trabalham os Estados em conjunto?' },
        { who: 'vet', fr: 'Chaque année, ils passent en revue les règles sanitaires qui touchent le commerce dans l’Union, pour les harmoniser ou les supprimer peu à peu. Les règles doivent être cohérentes, simples et transparentes, sans entraves inutiles.', en: 'Each year, they review the health rules that affect trade in the Union, to harmonise them or phase them out. Rules must be coherent, simple and transparent, with no needless barriers.', pt: 'Todos os anos, revêm as regras sanitárias que afetam o comércio na União, para as harmonizar ou eliminar progressivamente. As regras devem ser coerentes, simples e transparentes, sem entraves inúteis.' },
        { who: 'host', sting: true, fr: 'Revenons à Koffi. Un jour, un vendeur lui propose de la viande moins chère, sans cachet d’inspection.', en: 'Back to Koffi. One day, a trader offers him cheaper meat with no inspection stamp.', pt: 'Voltemos a Koffi. Um dia, um vendedor propõe-lhe carne mais barata, sem carimbo de inspeção.' },
        { who: 'vet', fr: 'Koffi refuse. Une viande non inspectée peut rendre des clients malades, et la boutique peut alors être fermée le temps de l’enquête. Tout établissement du domaine de la santé animale est soumis à l’inspection vétérinaire.', en: 'Koffi refuses. Uninspected meat can make customers ill, and then the shop can be closed during the investigation. Every establishment working in animal health is subject to veterinary inspection.', pt: 'Koffi recusa. Carne não inspecionada pode fazer adoecer clientes, e o talho pode então ser fechado durante a investigação. Todo o estabelecimento ligado à saúde animal está sujeito a inspeção veterinária.' },
        { who: 'host', fr: 'Alors, quelles sont les obligations de Koffi ?', en: 'So what are Koffi’s duties?', pt: 'Então, quais são as obrigações de Koffi?' },
        { who: 'vet', fr: 'Les opérateurs du secteur alimentaire répondent de la qualité sanitaire de ce qu’ils vendent, et ne vendent que des produits sûrs. Chacun contrôle ses propres opérations, à chaque étape.', en: 'Food businesses answer for the safety of what they sell, and sell only safe products. Each one checks its own operations at every stage.', pt: 'Os operadores do setor alimentar respondem pela qualidade sanitária do que vendem, e só vendem produtos seguros. Cada um controla as suas próprias operações, em cada etapa.' },
        { who: 'vet', fr: 'Et chacun doit pouvoir montrer aux inspecteurs ses autocontrôles et les informations commerciales sur ses denrées. C’est pourquoi Koffi note chaque achat : la date, le fournisseur, l’origine des animaux.', en: 'And each must be able to show inspectors its own checks and the trade records for its food. That’s why Koffi writes down every purchase: the date, the supplier, where the animals came from.', pt: 'E cada um deve poder mostrar aos inspetores os seus autocontrolos e as informações comerciais sobre os seus produtos. Por isso Koffi anota cada compra: a data, o fornecedor, a origem dos animais.' },
        { who: 'host', fr: 'C’est ce qu’on appelle la traçabilité.', en: 'That’s what people call traceability.', pt: 'É o que se chama rastreabilidade.' },
        { who: 'vet', fr: 'Oui : savoir d’où vient un produit et où il va. C’est l’habitude qui rend ces justificatifs possibles.', en: 'Yes: knowing where a product comes from and where it goes. It’s the habit that makes those records possible.', pt: 'Sim: saber de onde vem um produto e para onde vai. É o hábito que torna esses registos possíveis.' },
        { who: 'host', sting: true, fr: 'Une alerte arrive sur un lot de viande. Que doit faire Koffi ?', en: 'An alert comes in about a batch of meat. What should Koffi do?', pt: 'Chega um alerta sobre um lote de carne. O que deve fazer Koffi?' },
        { who: 'vet', fr: 'Aider les services. Grâce à son cahier, le lot est retrouvé et retiré, et le reste du marché continue.', en: 'Help the services. Thanks to his notebook, the batch is found and withdrawn, and the rest of the market carries on.', pt: 'Ajudar os serviços. Graças ao caderno, o lote é encontrado e retirado, e o resto do mercado continua.' },
        { who: 'host', fr: 'Et si c’est l’opérateur qui soupçonne un problème ?', en: 'And if it’s the business that suspects a problem?', pt: 'E se for o operador a suspeitar de um problema?' },
        { who: 'vet', fr: 'Le règlement est clair : s’il pense qu’une denrée qu’il a vendue peut nuire à la santé, il doit informer les autorités et prendre toute mesure pour éviter un dommage aux consommateurs.', en: 'The regulation is clear: if it thinks a food it has sold may harm health, it must inform the authorities and take every measure to prevent harm to consumers.', pt: 'O regulamento é claro: se pensar que um alimento que vendeu pode prejudicar a saúde, deve informar as autoridades e tomar todas as medidas para evitar danos aos consumidores.' },
        { who: 'host', fr: 'Et que peuvent faire les autorités ?', en: 'And what can the authorities do?', pt: 'E o que podem fazer as autoridades?' },
        { who: 'vet', fr: 'En cas de danger grave ou immédiat, l’organisme national peut suspendre la vente, retirer la denrée ou la faire détruire. En urgence, les autorités locales peuvent agir un mois au plus, en informant l’organisme national dans les vingt-quatre heures.', en: 'In serious or immediate danger, the national food safety body can suspend sales, withdraw the food or have it destroyed. In an emergency, local authorities can act for up to a month, informing the national body within twenty-four hours.', pt: 'Em caso de perigo grave ou imediato, o organismo nacional pode suspender a venda, retirar o alimento ou mandá-lo destruir. Em urgência, as autoridades locais podem agir até um mês, informando o organismo nacional em vinte e quatro horas.' },
        { who: 'host', fr: 'Et sur place, que peuvent faire les inspecteurs ?', en: 'And on the spot, what can inspectors do?', pt: 'E no local, o que podem fazer os inspetores?' },
        { who: 'vet', fr: 'Visiter les locaux, saisir des documents, prélever des échantillons et consigner des denrées. Ils peuvent demander qu’une denrée non conforme soit saisie, détruite ou envoyée ailleurs.', en: 'Visit premises, take documents and samples, and hold foods. They can ask for non-compliant food to be seized, destroyed or sent elsewhere.', pt: 'Visitar as instalações, apreender documentos, colher amostras e reter alimentos. Podem pedir que um alimento não conforme seja apreendido, destruído ou enviado para outro destino.' },
        { who: 'host', sting: true, fr: 'Parlons des maladies animales.', en: 'Let’s talk about animal diseases.', pt: 'Falemos das doenças animais.' },
        { who: 'vet', fr: 'En 2009, l’UEMOA a dressé la liste des maladies animales à déclaration obligatoire : plus de cent vingt. Parmi elles, la fièvre aphteuse, la péripneumonie contagieuse bovine, la peste des petits ruminants et la fièvre charbonneuse.', en: 'In 2009, WAEMU listed the animal diseases that must be notified: more than one hundred and twenty. Among them, foot-and-mouth disease, contagious bovine pleuropneumonia, peste des petits ruminants and anthrax.', pt: 'Em 2009, a UEMOA estabeleceu a lista das doenças animais de declaração obrigatória: mais de cento e vinte. Entre elas, a febre aftosa, a peripneumonia contagiosa bovina, a peste dos pequenos ruminantes e o carbúnculo hemático.' },
        { who: 'host', fr: 'Imaginons qu’un éleveur propose à Koffi des bovins qui bavent, avec des plaies dans la bouche.', en: 'Imagine a herder offers Koffi cattle that are drooling, with sores in their mouths.', pt: 'Imaginemos que um criador propõe a Koffi bovinos que babam, com feridas na boca.' },
        { who: 'vet', fr: 'Koffi refuse et alerte les services vétérinaires. Toute suspicion d’une maladie à déclaration obligatoire doit être portée immédiatement à la connaissance de l’autorité vétérinaire.', en: 'Koffi refuses and alerts the veterinary services. Any suspicion of a notifiable disease must be brought to the veterinary authority at once.', pt: 'Koffi recusa e alerta os serviços veterinários. Qualquer suspeita de doença de declaração obrigatória deve ser levada de imediato ao conhecimento da autoridade veterinária.' },
        { who: 'host', fr: 'Et ensuite ?', en: 'And then?', pt: 'E depois?' },
        { who: 'vet', fr: 'L’État notifie aussitôt la Commission de l’UEMOA, par écrit, sur le formulaire de l’OMSA. Il déclare l’infection et applique des mesures dans un périmètre déterminé.', en: 'The state notifies the WAEMU Commission immediately, in writing, on WOAH’s form. It declares the infection and applies measures within a defined area.', pt: 'O Estado notifica de imediato a Comissão da UEMOA, por escrito, no formulário da OMSA. Declara a infeção e aplica medidas num perímetro determinado.' },
        { who: 'host', fr: 'Quels événements faut-il notifier ?', en: 'Which events must be notified?', pt: 'Que acontecimentos devem ser notificados?' },
        { who: 'vet', fr: 'Pas seulement l’apparition d’une maladie de la liste, mais aussi son retour, une nouvelle souche, une hausse soudaine des animaux malades ou morts, ou une maladie émergente qui peut passer les frontières ou toucher l’homme.', en: 'Not only a listed disease appearing, but also its return, a new strain, a sudden rise in sick or dead animals, or an emerging disease that could cross borders or pass to people.', pt: 'Não só o aparecimento de uma doença da lista, mas também o seu regresso, uma nova estirpe, um aumento súbito de animais doentes ou mortos, ou uma doença emergente que possa atravessar fronteiras ou passar para as pessoas.' },
        { who: 'host', fr: 'Et en cas de vraie crise ?', en: 'And in a real crisis?', pt: 'E em caso de crise a sério?' },
        { who: 'vet', fr: 'Les États préviennent aussitôt la Commission et les autres États par le réseau d’alerte. Ils prennent des mesures de sauvegarde et informent l’OMSA. Les mesures prennent fin une fois la crise éradiquée.', en: 'States warn the Commission and each other at once through the alert network. They take safeguard measures and inform WOAH. The measures end once the crisis is eradicated.', pt: 'Os Estados avisam de imediato a Comissão e os outros Estados através da rede de alerta. Tomam medidas de salvaguarda e informam a OMSA. As medidas terminam quando a crise é erradicada.' },
        { who: 'host', fr: 'Et si un État n’arrive pas à faire face ?', en: 'And if a state can’t cope?', pt: 'E se um Estado não conseguir fazer face?' },
        { who: 'vet', fr: 'La Commission de l’UEMOA peut alors réunir d’urgence les organismes nationaux pour arrêter ensemble les mesures à prendre. Et l’Union encourage chaque État à créer un fonds national d’urgence sanitaire.', en: 'Then the WAEMU Commission can urgently call the national bodies together to agree on the measures to take. And the Union encourages each state to set up a national health emergency fund.', pt: 'A Comissão da UEMOA pode então reunir com urgência os organismos nacionais para decidirem em conjunto as medidas a tomar. E a União incentiva cada Estado a criar um fundo nacional de emergência sanitária.' },
        { who: 'host', sting: true, fr: 'Et le commerce entre États membres ?', en: 'What about trade between member states?', pt: 'E o comércio entre Estados-membros?' },
        { who: 'vet', fr: 'Les animaux envoyés vers un autre État membre voyagent avec un certificat vétérinaire délivré par un vétérinaire officiel. La viande et les produits d’origine animale qui entrent dans l’Union ont un certificat de salubrité : animaux sains, préparation et conservation hygiéniques.', en: 'Animals sent to another member state travel with a veterinary certificate from an official vet. Meat and animal products entering the Union carry a health certificate: healthy animals, hygienic preparation and storage.', pt: 'Os animais enviados para outro Estado-membro viajam com um certificado veterinário emitido por um veterinário oficial. A carne e os produtos de origem animal que entram na União têm um certificado de salubridade: animais saudáveis, preparação e conservação higiénicas.' },
        { who: 'host', fr: 'Un voisin peut-il fermer ses portes ?', en: 'Can a neighbour close its doors?', pt: 'Um vizinho pode fechar as portas?' },
        { who: 'vet', fr: 'En cas d’épizootie, un État peut restreindre les animaux venant des seules parties touchées d’un autre État, ou de tout son territoire si la maladie s’étend largement. Sinon, les produits conformes circulent librement, et tout opérateur peut les vendre dans un autre État membre.', en: 'In an epizootic, a state can restrict animals from just the affected parts of another state, or from all of it if the disease spreads widely. Otherwise, products that meet the rules move freely, and any business can sell them in another member state.', pt: 'Em caso de epizootia, um Estado pode restringir os animais vindos apenas das partes afetadas de outro Estado, ou de todo o território se a doença se alastrar muito. Caso contrário, os produtos conformes circulam livremente, e qualquer operador pode vendê-los noutro Estado-membro.' },
        { who: 'host', fr: 'Et quand Koffi est contrôlé ?', en: 'And when Koffi is inspected?', pt: 'E quando Koffi é controlado?' },
        { who: 'vet', fr: 'Il a droit à la transparence, à l’impartialité et à la proportionnalité. Et les États informent les acteurs des risques et des mesures prises.', en: 'He is entitled to transparency, impartiality and proportionality. And states keep people informed about risks and the measures taken.', pt: 'Tem direito à transparência, à imparcialidade e à proporcionalidade. E os Estados informam os intervenientes sobre os riscos e as medidas tomadas.' },
        { who: 'host', sting: true, fr: 'Docteur, que doivent retenir nos auditeurs ?', en: 'Doctor, what should our listeners remember?', pt: 'Doutor, o que devem reter os nossos ouvintes?' },
        { who: 'vet', fr: 'Quatre règles. Ne vendre que des produits sûrs. Garder ses justificatifs. Informer les autorités sans attendre. Et signaler toute maladie suspecte.', en: 'Four rules. Sell only safe products. Keep your records. Inform the authorities at once. And report any suspected disease.', pt: 'Quatro regras. Vender só produtos seguros. Guardar os registos. Informar as autoridades sem esperar. E comunicar qualquer doença suspeita.' },
        { who: 'host', fr: 'Merci, docteur.', en: 'Thank you, Doctor.', pt: 'Obrigado, doutor.' },
        { who: 'host', sting: true, fr: 'À retenir : viande inspectée, achats notés, et tout problème signalé aux services vétérinaires. À bientôt sur « Santé animale, marchés ouverts ».', en: 'Remember: inspected meat, purchases recorded, and any problem reported to the veterinary services. See you next time on Healthy Animals, Open Markets.', pt: 'A reter: carne inspecionada, compras anotadas, e qualquer problema comunicado aos serviços veterinários. Até breve em «Animais saudáveis, mercados abertos».' },
      ],
    },
  ],
  credit: { fr: 'Une production Paruto Media.', en: 'A Paruto Media production.', pt: 'Uma produção Paruto Media.' },
};
